package application.adapters.persistence.jpa.entities;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import lombok.Getter;
import lombok.NoArgsConstructor;
import lombok.Setter;

import java.math.BigDecimal;

/**
 * JPA persistence entity for ReturnRefund (inferred class).
 */
@Entity
@Table(name = "return_refunds")
@Getter
@Setter
@NoArgsConstructor
public class ReturnRefundJpaEntity {

    /** ReturnRefund.identifier (decision D2), generated by the adapter. */
    @Id
    @Column(name = "identifier", nullable = false, length = 60)
    private String identifier;

    @Column(name = "order_identifier", nullable = false, length = 60)
    private String orderIdentifier;

    @Column(name = "reason", length = 500)
    private String reason;

    /** ReturnStatus enum name. */
    @Column(name = "status", length = 20)
    private String status;

    @Column(name = "refunded_amount", precision = 19, scale = 2)
    private BigDecimal refundedAmount;
}
